// Seed A — Behavioral adder.
// Lets the synthesizer pick the best gate-level adder topology for the
// target library; typically yields the smallest area and good delay.
module adder_32bit(A, B, S, C32);
    input  [31:0] A;
    input  [31:0] B;
    output [31:0] S;
    output        C32;

    assign {C32, S} = A + B;
endmodule

// Seed B — Hierarchical 16-bit carry-lookahead blocks.
// Matches the "adder_32bit consists of several 16-bit CLA blocks" spec.
// Uses standard OR-based carry equations (vs. the reference's non-standard
// XOR form) and a clean parameterizable carry chain inside each block.
module adder_32bit(A, B, S, C32);
    input  [31:0] A;
    input  [31:0] B;
    output [31:0] S;
    output        C32;

    wire c16;

    cla16 cla_lo (.A(A[15:0]),  .B(B[15:0]),  .cin(1'b0), .S(S[15:0]),  .cout(c16));
    cla16 cla_hi (.A(A[31:16]), .B(B[31:16]), .cin(c16),  .S(S[31:16]), .cout(C32));
endmodule

module cla16(A, B, cin, S, cout);
    input  [15:0] A;
    input  [15:0] B;
    input         cin;
    output [15:0] S;
    output        cout;

    wire [15:0] p = A ^ B;
    wire [15:0] g = A & B;
    wire [16:0] c;
    assign c[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : carry_chain
            assign c[i+1] = g[i] | (p[i] & c[i]);
        end
    endgenerate

    assign S    = p ^ c[15:0];
    assign cout = c[16];
endmodule

// Seed C — 16/16 carry-select adder.
// Computes both possible high halves speculatively (cin=0 and cin=1) and
// muxes based on the low half's carry-out. Shorter critical path at the cost
// of a duplicated upper adder.
module adder_32bit(A, B, S, C32);
    input  [31:0] A;
    input  [31:0] B;
    output [31:0] S;
    output        C32;

    wire [16:0] sum_lo  = {1'b0, A[15:0]}  + {1'b0, B[15:0]};
    wire [16:0] sum_hi0 = {1'b0, A[31:16]} + {1'b0, B[31:16]};
    wire [16:0] sum_hi1 = {1'b0, A[31:16]} + {1'b0, B[31:16]} + 17'd1;

    wire        c16    = sum_lo[16];
    wire [16:0] sum_hi = c16 ? sum_hi1 : sum_hi0;

    assign S   = {sum_hi[15:0], sum_lo[15:0]};
    assign C32 = sum_hi[16];
endmodule

// Seed D — 32-bit Kogge-Stone parallel-prefix adder.
// log2(32)=5 prefix stages; all positions get their prefix (G,P) in parallel.
// Shortest logical depth of the four seeds.
module adder_32bit(A, B, S, C32);
    input  [31:0] A;
    input  [31:0] B;
    output [31:0] S;
    output        C32;

    wire [31:0] p0 = A ^ B;
    wire [31:0] g0 = A & B;

    wire [31:0] g1, p1, g2, p2, g3, p3, g4, p4, g5, p5;

    genvar i;
    // Stage 1: combine with neighbour 1 away
    generate for (i = 0; i < 32; i = i + 1) begin : st1
        if (i < 1) begin
            assign g1[i] = g0[i];
            assign p1[i] = p0[i];
        end else begin
            assign g1[i] = g0[i] | (p0[i] & g0[i-1]);
            assign p1[i] = p0[i] & p0[i-1];
        end
    end endgenerate

    // Stage 2: span 2
    generate for (i = 0; i < 32; i = i + 1) begin : st2
        if (i < 2) begin
            assign g2[i] = g1[i];
            assign p2[i] = p1[i];
        end else begin
            assign g2[i] = g1[i] | (p1[i] & g1[i-2]);
            assign p2[i] = p1[i] & p1[i-2];
        end
    end endgenerate

    // Stage 3: span 4
    generate for (i = 0; i < 32; i = i + 1) begin : st3
        if (i < 4) begin
            assign g3[i] = g2[i];
            assign p3[i] = p2[i];
        end else begin
            assign g3[i] = g2[i] | (p2[i] & g2[i-4]);
            assign p3[i] = p2[i] & p2[i-4];
        end
    end endgenerate

    // Stage 4: span 8
    generate for (i = 0; i < 32; i = i + 1) begin : st4
        if (i < 8) begin
            assign g4[i] = g3[i];
            assign p4[i] = p3[i];
        end else begin
            assign g4[i] = g3[i] | (p3[i] & g3[i-8]);
            assign p4[i] = p3[i] & p3[i-8];
        end
    end endgenerate

    // Stage 5: span 16
    generate for (i = 0; i < 32; i = i + 1) begin : st5
        if (i < 16) begin
            assign g5[i] = g4[i];
            assign p5[i] = p4[i];
        end else begin
            assign g5[i] = g4[i] | (p4[i] & g4[i-16]);
            assign p5[i] = p4[i] & p4[i-16];
        end
    end endgenerate

    // Carry into bit i is the prefix-G of bits 0..i-1; cin assumed 0.
    wire [31:0] c;
    assign c[0] = 1'b0;
    generate for (i = 1; i < 32; i = i + 1) begin : carries
        assign c[i] = g5[i-1];
    end endgenerate

    assign S   = p0 ^ c;
    assign C32 = g5[31];
endmodule
